{"perguntas":[
 {"t":"multipla","p":"A que é necessário se apegar com mais diligência?","o":["Às coisas que já ouvimos","Às tradições dos anciãos","Às visões dos profetas","Aos sacrifícios do templo"],"c":0,"v":1,"e":"O versículo 1 diz que devemos nos apegar com mais diligência às coisas que já ouvimos, para não nos desviarmos delas."},
 {"t":"multipla","p":"Por quem a salvação foi inicialmente anunciada?","o":["Pelos anjos","Pelos profetas","Pelo Senhor","Por Moisés"],"c":2,"v":3,"e":"O versículo 3 diz que a salvação foi anunciada inicialmente pelo Senhor e depois confirmada pelos que a ouviram."},
 {"t":"multipla","p":"Como Deus testificou junto com os que ouviram o Senhor?","o":["Por sonhos e visões","Por leis escritas em pedra","Por sacrifícios no altar","Por sinais, prodígios e diversos milagres"],"c":3,"v":4,"e":"O versículo 4 diz que Deus testificou por meio de sinais, prodígios, diversos milagres e da distribuição do Espírito Santo."},
 {"t":"multipla","p":"Pela graça de Deus, Jesus provou a morte por quem?","o":["Pelos anjos","Por todo homem","Somente pelos sacerdotes","Somente pelos apóstolos"],"c":1,"v":9,"e":"O versículo 9 diz que Jesus provou a morte por todo homem, pela graça de Deus."},
 {"t":"multipla","p":"Quem é aquele que tem o poder da morte, que Jesus destruiu por meio da morte?","o":["O diabo","Faraó","O pecado de Adão","O sumo sacerdote"],"c":0,"v":14,"e":"O versículo 14 diz que, por meio da morte, ele destruiu aquele que tem o poder da morte, isto é, o diabo."},
 {"t":"cv","p":"O mundo futuro foi sujeitado aos anjos.","c":false,"v":5,"e":"O versículo 5 diz que não foi a anjos que Deus sujeitou o mundo futuro."},
 {"t":"cv","p":"Ele não se envergonha de chamar de irmãos os que são santificados.","c":true,"v":11,"e":"O versículo 11 diz que, por terem todos origem em um só, ele não se envergonha de lhes chamar irmãos."},
 {"t":"cv","p":"Ele se tornou semelhante aos irmãos para ser um sumo sacerdote misericordioso e fiel.","c":true,"v":17,"e":"O versículo 17 diz que era necessário que ele se tornasse semelhante aos irmãos em todas as coisas para ser um sumo sacerdote misericordioso e fiel."}
]}
